import{_ as t,o,c as r,a2 as a}from"./chunks/framework.BXzK3EA4.js";const i="/assets/Amibroker%20Charts%20(1).YBdFq0YX.png",n="/assets/image%20(134).CD5g8_vs.png",l="/assets/image%20(133).Bu7r8CZO.png",s="/assets/image%20(135).ClnlHoTD.png",d="/assets/image%20(136).j52dB651.png",c="/assets/image%20(137).CItzoBJO.png",u="/assets/image%20(138).hM8i-Ntz.png",T=JSON.parse('{"title":"Amibroker Plugin","description":"","frontmatter":{},"headers":[],"relativePath":"trading-platform/amibroker/amibroker-plugin.md","filePath":"trading-platform/amibroker/amibroker-plugin.md"}'),h={name:"trading-platform/amibroker/amibroker-plugin.md"};function g(b,e,p,m,f,k){return o(),r("div",null,[...e[0]||(e[0]=[a('<h1 id="amibroker-plugin" tabindex="-1">Amibroker Plugin <a class="header-anchor" href="#amibroker-plugin" aria-label="Permalink to &quot;Amibroker Plugin&quot;">​</a></h1><h2 id="tradeboard-amibroker-plugin-setup-guide" tabindex="-1">Tradeboard Amibroker Plugin Setup Guide <a class="header-anchor" href="#tradeboard-amibroker-plugin-setup-guide" aria-label="Permalink to &quot;Tradeboard Amibroker Plugin Setup Guide&quot;">​</a></h2><p>This guide will walk you through the installation and configuration of the Tradeboard Plugin for AmiBroker.</p><h3 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h3><ul><li>AmiBroker 6.0 or higher installed on your system</li><li>Tradeboard server running (ensure it&#39;s accessible at your configured host URL)</li><li>Your Tradeboard API key</li></ul><h3 id="features" tabindex="-1">Features <a class="header-anchor" href="#features" aria-label="Permalink to &quot;Features&quot;">​</a></h3><ul><li>1-minute intraday history, with manual backfill of 3 months, 6 months or 1 year</li><li>Daily (EOD) history, with manual backfill of 5, 10 or 25 years</li><li>Automatic intraday refresh on a configurable cadence, seeded from the existing cache so only new bars are fetched</li><li>Realtime chart candles built from live WebSocket ticks</li><li>Realtime Quote Window fed from live WebSocket quote and depth frames</li><li>WebSocket reconnect, ping/pong and automatic resubscription</li><li>Connects to all Tradeboard-supported brokers that provide historical data and live quotes</li><li>Exchange coverage follows Tradeboard: NSE, NSE_INDEX, BSE, BSE_INDEX, NFO, BFO, MCX, CDS and the other Tradeboard exchanges</li><li>Symbol format is <code>TRADEBOARD_SYMBOL-TRADEBOARD_EXCHANGE</code>, for example <code>INFY-NSE</code>, <code>CRUDEOIL19NOV25FUT-MCX</code>, <code>TCS-BSE</code></li><li>Coloured status indicator in the AmiBroker status bar</li><li>Supports mixed EOD/intraday databases</li></ul><p>The plugin uses two separate channels, and both have to be reachable:</p><ul><li><strong>Historical data</strong> comes from the Tradeboard REST API, <code>POST /api/v1/history</code>, on the HTTP port (default <code>5000</code>). The plugin requests <code>interval=1m</code> for 1-minute charts and <code>interval=D</code> for daily charts. No other Tradeboard interval is exposed through the plugin.</li><li><strong>Live data</strong> comes from the Tradeboard WebSocket proxy (default <code>ws://127.0.0.1:8765</code>). The plugin authenticates with your Tradeboard API key, then subscribes each symbol in mode 1 (LTP), mode 2 (Quote) and mode 3 (Depth).</li></ul><p>Streaming windows deliberately do not fall back to <code>POST /api/v1/quotes</code>. Live charts and the Quote Window therefore stay empty when the WebSocket connection is down, even if <strong>Test Connection</strong> on the HTTP side succeeds.</p><figure><img src="'+i+'" alt=""><figcaption></figcaption></figure><h3 id="installation-steps" tabindex="-1">Installation Steps <a class="header-anchor" href="#installation-steps" aria-label="Permalink to &quot;Installation Steps&quot;">​</a></h3><h4 id="_1-download-the-plugin" tabindex="-1">1. Download the Plugin <a class="header-anchor" href="#_1-download-the-plugin" aria-label="Permalink to &quot;1. Download the Plugin&quot;">​</a></h4><p>Download the <a href="https://github.com/marketcalls/TradeboardPlugin/releases" target="_blank" rel="noreferrer">Tradeboard Amibroker Plugin</a> from the official release page:</p><figure><img src="'+n+'" alt=""><figcaption></figcaption></figure><h4 id="_2-extract-the-plugin" tabindex="-1">2. Extract the Plugin <a class="header-anchor" href="#_2-extract-the-plugin" aria-label="Permalink to &quot;2. Extract the Plugin&quot;">​</a></h4><p>Extract the downloaded <code>Tradeboard.Plugin.zip</code> file. You&#39;ll find two folders:</p><ul><li><code>32bit</code> - For 32-bit AmiBroker installations</li><li><code>64bit</code> - For 64-bit AmiBroker installations</li></ul><figure><img src="'+l+'" alt=""><figcaption></figcaption></figure><h4 id="_3-close-amibroker" tabindex="-1">3. Close AmiBroker <a class="header-anchor" href="#_3-close-amibroker" aria-label="Permalink to &quot;3. Close AmiBroker&quot;">​</a></h4><p><strong>IMPORTANT:</strong> If AmiBroker is currently running, close it completely before proceeding. This ensures the plugin loads correctly when AmiBroker restarts.</p><h4 id="_4-copy-the-plugin-file" tabindex="-1">4. Copy the Plugin File <a class="header-anchor" href="#_4-copy-the-plugin-file" aria-label="Permalink to &quot;4. Copy the Plugin File&quot;">​</a></h4><ol><li><p>Navigate to the appropriate folder based on your AmiBroker version:</p><ul><li>For 64-bit AmiBroker: Open the <code>64bit</code> folder</li><li>For 32-bit AmiBroker: Open the <code>32bit</code> folder</li></ul></li><li><p>Copy the <code>Tradeboard.dll</code> file</p></li><li><p>Paste it into your AmiBroker Plugins folder, typically located at:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C:\\Program Files\\AmiBroker\\Plugins\\</span></span></code></pre></div><p>or</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>C:\\Program Files (x86)\\AmiBroker\\Plugins\\</span></span></code></pre></div></li></ol><figure><img src="'+s+'" alt=""><figcaption></figcaption></figure><h4 id="_5-restart-amibroker" tabindex="-1">5. Restart AmiBroker <a class="header-anchor" href="#_5-restart-amibroker" aria-label="Permalink to &quot;5. Restart AmiBroker&quot;">​</a></h4><p>Launch AmiBroker. The Tradeboard plugin should now be loaded automatically.</p><h3 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h3><h4 id="_1-create-open-amibroker-database" tabindex="-1">1. Create/Open AmiBroker Database <a class="header-anchor" href="#_1-create-open-amibroker-database" aria-label="Permalink to &quot;1. Create/Open AmiBroker Database&quot;">​</a></h4><ol><li>In AmiBroker, create a new database or open an existing one</li><li>When creating a database, select <strong>Tradeboard Plugin</strong> as the data source</li><li>Set the Number of Bars as 75000 for sufficient amount of backfill data</li><li>Set the Base Time Interval as 1-minute</li></ol><figure><img src="'+d+'" alt=""><figcaption></figcaption></figure><h4 id="_2-configure-intraday-settings" tabindex="-1">2. Configure Intraday Settings <a class="header-anchor" href="#_2-configure-intraday-settings" aria-label="Permalink to &quot;2. Configure Intraday Settings&quot;">​</a></h4><ol><li>Click on <strong>Intraday</strong> <strong>Settings button</strong></li><li>Select the option: <strong>&quot;Allow mixed EOD/intraday data&quot;</strong></li><li>Click <strong>OK</strong> to save</li></ol><figure><img src="'+c+'" alt=""><figcaption></figcaption></figure><h4 id="_3-configure-tradeboard-plugin-settings" tabindex="-1">3. Configure Tradeboard Plugin Settings <a class="header-anchor" href="#_3-configure-tradeboard-plugin-settings" aria-label="Permalink to &quot;3. Configure Tradeboard Plugin Settings&quot;">​</a></h4><ol><li>Click on <strong>Configure Button</strong> (also reachable from <strong>File</strong> -&gt; <strong>Database Settings</strong> -&gt; <strong>Configure</strong>)</li><li>Configure the <strong>Server Settings</strong>: <ul><li><strong>Server</strong>: Enter your Tradeboard server address (e.g., <code>127.0.0.1</code>)</li><li><strong>Port</strong>: Enter the port number (default: <code>5000</code>)</li><li><strong>API Key</strong>: Enter your Tradeboard API key</li><li><strong>Backfill Refresh (sec)</strong>: How often the plugin re-fetches 1-minute history for cached symbols (default: <code>30</code>). It does not control the live tick rate, which is driven by the WebSocket feed. The connection heartbeat is fixed internally at 30 seconds.</li><li><strong>Time Shift (hours)</strong>: Set time shift if needed (default: <code>0</code>)</li></ul></li><li>Click <strong>Test Connection</strong> to verify server connectivity</li><li>Configure the <strong>WebSocket Settings</strong>: <ul><li><strong>WebSocket URL</strong>: Enter your WebSocket URL (e.g., <code>ws://127.0.0.1:8765</code>)</li><li>Click <strong>Test WebSocket</strong> to verify the connection</li><li>Monitor the <strong>WebSocket Status</strong> field</li></ul></li><li>Verify the <strong>Connection Status</strong> shows as &quot;Ready&quot;</li><li>Click <strong>OK</strong> to save all settings</li></ol><figure><img src="'+u+'" alt=""><figcaption></figcaption></figure><h4 id="_4-add-symbols" tabindex="-1">4. Add Symbols <a class="header-anchor" href="#_4-add-symbols" aria-label="Permalink to &quot;4. Add Symbols&quot;">​</a></h4><ol><li>In AmiBroker, go to <strong>Symbol</strong> &gt; <strong>New</strong> to add a new symbol</li><li>Click <strong>New</strong> to add a new symbol</li><li>Enter the symbol ticker (e.g., <code>SBIN-NSE</code>, <code>RELIANCE-BSE</code>, <code>NIFTY-NSE_INDEX</code>, <code>CRUDEOIL18JUN26FUT-MCX</code>)</li><li>symbol format is <code>tradeboard symbol-tradeboard exchange</code></li><li>If the exchange suffix is omitted the plugin falls back to <code>NSE</code>, which is wrong for futures, options, MCX and BSE symbols, so always include it</li><li>The plugin will automatically fetch live data for the symbol</li></ol><h4 id="_5-backfill-history" tabindex="-1">5. Backfill History <a class="header-anchor" href="#_5-backfill-history" aria-label="Permalink to &quot;5. Backfill History&quot;">​</a></h4><p>Right-click the Tradeboard status area in the AmiBroker status bar to open the plugin menu. Apart from <strong>Connect</strong>, <strong>Disconnect</strong> and <strong>Configure...</strong>, it offers:</p><ul><li><strong>Backfill 1-Minute Data</strong>: 3 Months, 6 Months or 1 Year, for the current symbol or for all symbols</li><li><strong>Backfill Daily Data</strong>: 5 Years, 10 Years or 25 Years, for the current symbol or for all symbols</li></ul><p>&quot;Current symbol&quot; is the active chart symbol. &quot;All symbols&quot; covers the symbols already in the chart cache or subscribed over the WebSocket. Backfill runs one symbol at a time on purpose, so a large &quot;All Symbols&quot; request finishes sequentially rather than bursting requests at your broker.</p><h3 id="verification" tabindex="-1">Verification <a class="header-anchor" href="#verification" aria-label="Permalink to &quot;Verification&quot;">​</a></h3><ol><li>Ensure Tradeboard server is running in the background</li><li>Add a symbol in AmiBroker</li><li>Open a chart for the symbol</li><li>You should see live data streaming into the chart</li><li>Check the AmiBroker log window for any connection or data errors</li></ol><p>The plugin status area in the AmiBroker status bar reports the connection state as a coloured indicator:</p><table tabindex="0"><thead><tr><th>Indicator</th><th>Colour</th><th>Meaning</th></tr></thead><tbody><tr><td>WAIT</td><td>Yellow</td><td>Waiting for connection</td></tr><tr><td>OK</td><td>Green</td><td>Connected</td></tr><tr><td>ERR</td><td>Red</td><td>Disconnected or error</td></tr><tr><td>OFF</td><td>Purple</td><td>Shut down by the user</td></tr><tr><td>???</td><td>Grey</td><td>State unknown</td></tr></tbody></table><h3 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h3><h4 id="plugin-not-loading" tabindex="-1">Plugin Not Loading <a class="header-anchor" href="#plugin-not-loading" aria-label="Permalink to &quot;Plugin Not Loading&quot;">​</a></h4><ul><li>Verify you copied the correct DLL version (32-bit or 64-bit) matching your AmiBroker installation</li><li>Ensure AmiBroker was restarted after copying the plugin</li><li>Check Windows Event Viewer for any DLL loading errors</li></ul><h4 id="connection-issues" tabindex="-1">Connection Issues <a class="header-anchor" href="#connection-issues" aria-label="Permalink to &quot;Connection Issues&quot;">​</a></h4><ul><li>Verify Tradeboard server is running</li><li>Check the Server address and Port are correct</li><li>Ensure your firewall is not blocking the connection</li><li>Test the API key directly with Tradeboard API</li></ul><h4 id="websocket-issues" tabindex="-1">WebSocket Issues <a class="header-anchor" href="#websocket-issues" aria-label="Permalink to &quot;WebSocket Issues&quot;">​</a></h4><ul><li>Verify the WebSocket URL is correct</li><li>Check if the WebSocket service is running on the Tradeboard server</li><li>Ensure port 8765 (or your configured port) is not blocked</li></ul><h4 id="no-data-appearing" tabindex="-1">No Data Appearing <a class="header-anchor" href="#no-data-appearing" aria-label="Permalink to &quot;No Data Appearing&quot;">​</a></h4><ul><li>Verify the symbol format matches what Tradeboard expects, including the <code>-EXCHANGE</code> suffix</li><li>Check the AmiBroker log window for error messages</li><li>Ensure Backfill Refresh (sec) is not set so high that intraday history stops catching up</li><li>Verify your broker&#39;s market data feed covers the requested symbols and that Tradeboard is logged in to the broker</li></ul><h4 id="known-limitations" tabindex="-1">Known Limitations <a class="header-anchor" href="#known-limitations" aria-label="Permalink to &quot;Known Limitations&quot;">​</a></h4><ul><li><strong>Time &amp; Sales is not populating reliably</strong> in the current release. The plugin subscribes to the required WebSocket streams but the Time &amp; Sales window may stay empty. Charts and the Realtime Quote Window are unaffected.</li><li>Only the 1-minute and Daily intervals are exposed. Other Tradeboard intervals are not available through the plugin.</li><li>Streaming windows are WebSocket-only by design. There is no REST quote polling fallback.</li></ul><h3 id="support" tabindex="-1">Support <a class="header-anchor" href="#support" aria-label="Permalink to &quot;Support&quot;">​</a></h3><p>For issues and support, please visit:</p><ul><li>GitHub Issues: <a href="https://github.com/marketcalls/TradeboardPlugin/issues" target="_blank" rel="noreferrer">https://github.com/marketcalls/TradeboardPlugin/issues</a></li><li>Tradeboard Documentation: <a href="https://docs.algo.wesoftcorp.com" target="_blank" rel="noreferrer">https://docs.algo.wesoftcorp.com</a></li></ul><h3 id="notes" tabindex="-1">Notes <a class="header-anchor" href="#notes" aria-label="Permalink to &quot;Notes&quot;">​</a></h3><ul><li>The plugin requires an active internet connection and running Tradeboard server connected with your broker</li><li>Ensure your Tradeboard server has valid broker credentials configured</li><li>Data availability depends on your broker&#39;s data feed and on the intervals your broker&#39;s history API supports</li><li>The WebSocket connection provides real-time tick data updates; the REST history API provides the completed bars behind them</li></ul>',62)])])}const S=t(h,[["render",g]]);export{T as __pageData,S as default};
